// Deterministic booking against the mock restaurant data. No LLM.
const RESTAURANTS = [{"id": "r1", "name": "Sunny Side Cafe", "cuisine": "American brunch", "neighborhood": "Downtown", "menu": [{"name": "Classic Eggs Benedict", "tags": ["dairy"]}, {"name": "Buttermilk Pancakes", "tags": ["vegetarian", "dairy", "gluten"]}, {"name": "Avocado Toast (GF bread available)", "tags": ["vegetarian", "vegan", "gluten-free-option"]}, {"name": "Veggie Omelette", "tags": ["vegetarian", "gluten-free", "dairy-optional"]}, {"name": "Fruit Bowl", "tags": ["vegetarian", "vegan", "gluten-free"]}], "slots": {"10:00": 6, "11:00": 4, "12:00": 2}}, {"id": "r2", "name": "Taco Tuesday (Open Sundays)", "cuisine": "Mexican", "neighborhood": "Mission", "menu": [{"name": "Chilaquiles", "tags": ["vegetarian", "dairy", "gluten-free"]}, {"name": "Breakfast Burrito", "tags": ["gluten", "dairy"]}, {"name": "Carnitas Tacos (corn tortilla)", "tags": ["gluten-free"]}, {"name": "Black Bean Tacos (corn tortilla)", "tags": ["vegetarian", "vegan", "gluten-free"]}], "slots": {"10:30": 8, "11:30": 8}}, {"id": "r3", "name": "The Green Fork", "cuisine": "Plant-based", "neighborhood": "Riverside", "menu": [{"name": "Tofu Scramble", "tags": ["vegetarian", "vegan", "gluten-free"]}, {"name": "Buckwheat Waffles", "tags": ["vegetarian", "vegan", "gluten-free"]}, {"name": "Cashew Cheese Bagel", "tags": ["vegetarian", "vegan", "gluten"]}, {"name": "Smoothie Bowl", "tags": ["vegetarian", "vegan", "gluten-free"]}], "slots": {"10:00": 4, "11:00": 4, "12:00": 4}}, {"id": "r4", "name": "Le Petit Croissant", "cuisine": "French bakery", "neighborhood": "Old Town", "menu": [{"name": "Croque Madame", "tags": ["gluten", "dairy"]}, {"name": "Butter Croissant", "tags": ["vegetarian", "gluten", "dairy"]}, {"name": "Quiche Lorraine", "tags": ["gluten", "dairy"]}, {"name": "Cafe au Lait", "tags": ["vegetarian", "dairy"]}], "slots": {"09:30": 3, "10:30": 3}}, {"id": "r5", "name": "Harbor Grill", "cuisine": "Seafood", "neighborhood": "Waterfront", "menu": [{"name": "Smoked Salmon Plate", "tags": ["gluten-free", "dairy-optional"]}, {"name": "Crab Cake Benedict", "tags": ["gluten", "dairy"]}, {"name": "Grilled Veggie Plate", "tags": ["vegetarian", "vegan", "gluten-free"]}, {"name": "Shrimp & Grits", "tags": ["gluten-free", "dairy"]}], "slots": {"11:00": 5, "12:00": 5, "13:00": 5}}];
const st = $getWorkflowStaticData('global');
st.booked = st.booked || {};      // "restaurant|date|time" -> seats taken
st.bookings = st.bookings || [];

const { restaurant_id, date, time, party_size } = $input.first().json;
const size = Number(party_size);
const r = RESTAURANTS.find(x => x.id === restaurant_id);
if (!r) return [{ json: { error: `Unknown restaurant_id ${restaurant_id}` } }];
if (!(time in r.slots)) return [{ json: { error: `${r.name} has no ${time} slot on ${date}` } }];

const key = `${restaurant_id}|${date}|${time}`;
const remaining = r.slots[time] - (st.booked[key] || 0);
if (remaining < size) return [{ json: { error: `Only ${remaining} seats left at ${r.name} ${date} ${time}` } }];

st.booked[key] = (st.booked[key] || 0) + size;
const booking = {
  confirmation_id: 'BR-' + Math.random().toString(16).slice(2, 8).toUpperCase(),
  restaurant_id,
  restaurant_name: r.name,
  address: `${r.neighborhood} (mock address)`,
  date, time, party_size: size,
};
st.bookings.push(booking);
return [{ json: booking }];
